<template>
  <section :class="['task-center',{embedded}]">
    <header class="task-center-heading"><div class="task-center-brand"><span><Activity :size="20" /></span><div><h2>AI 创作实况</h2><p>文字、图片、视频，每一次创作都有记录。</p></div></div><div class="task-center-heading-actions"><span :class="['live-state',{connected:connection==='live'}]"><i></i>{{ connection==='live'?'实时同步':connection==='polling'?'定时同步':'连接中' }}</span><button class="btn btn-sm" @click="refreshAll" :disabled="loading"><RefreshCw :size="12" :class="{'animate-spin':loading}" />刷新</button><button v-if="closable" class="btn btn-icon" @click="$emit('close')" aria-label="关闭任务日志"><X :size="17" /></button></div></header>
    <div class="task-center-body"><aside class="activity-sidebar"><div class="activity-filter-row"><label><Search :size="13" /><input v-model="keyword" placeholder="搜索本页任务" /></label><select v-model="kind" aria-label="任务类型"><option value="">全部类型</option><option value="text">文字</option><option value="image">图片</option><option value="video">视频</option></select></div><div class="activity-counts"><button :class="{on:status===''}" @click="status=''">全部 <b>{{ allCount }}</b></button><button :class="{on:status==='running'}" @click="status='running'"><i class="active-dot"></i>执行 {{ counts.active || 0 }}</button><button :class="{on:status==='queued'}" @click="status='queued'">排队 {{ counts.queued || 0 }}</button><button :class="{on:status==='completed'}" @click="status='completed'">完成 {{ counts.completed || 0 }}</button><button :class="{on:status==='failed'}" @click="status='failed'">失败 {{ counts.failed || 0 }}</button></div><p v-if="listError" class="activity-error" role="alert">{{ listError }}</p><div class="activity-list"><button v-for="task in visibleItems" :key="task.id" :class="['activity-item',{selected:task.id===selectedId}]" @click="select(task.id)"><span :class="['activity-item-icon',task.kind]"><component :is="kindIcon(task.kind)" :size="16" /><i v-if="activityTaskActive(task)" class="activity-item-running"></i></span><span class="activity-item-main"><strong>{{ task.title || activityKindLabel(task.kind)+'任务' }}</strong><span>{{ task.model || task.channel || '等待分配模型' }}</span><small><i :class="stateClass(task)"></i>{{ activityStatusLabel(task) }}<b>·</b>{{ activitySeconds(activityElapsed(task,clock)) }}</small></span><ChevronRight :size="12" /></button><div v-if="!visibleItems.length" class="activity-empty"><Loader2 v-if="loading" :size="24" class="animate-spin" /><ListTodo v-else :size="27" /><strong>{{ loading?'正在读取任务…':keyword?'没有匹配任务':'还没有创作记录' }}</strong><p v-if="!loading">{{ keyword?'试试其他名称。':'开始创作后，这里会持续记录运行过程。' }}</p></div></div><footer class="activity-pagination"><button :disabled="offset===0 || loading" @click="offset=Math.max(0,offset-limit)"><ChevronLeft :size="13" />上一页</button><span>{{ total?`${offset+1}–${Math.min(offset+limit,total)}`:'0' }} / {{ total }}</span><button :disabled="offset+limit>=total || loading" @click="offset+=limit">下一页<ChevronRight :size="13" /></button></footer></aside>
      <main class="activity-detail"><template v-if="selectedTask"><header class="activity-detail-header"><div><p>{{ activityKindLabel(selectedTask.kind) }}任务 · {{ formatDate(selectedTask.created_at || selectedTask.started_at) }}</p><h1>{{ selectedTask.title || '创作任务' }}</h1><div class="activity-detail-meta"><span :class="['activity-status-chip',stateClass(selectedTask)]"><i></i>{{ activityStatusLabel(selectedTask) }}</span><span>{{ activityStageLabel(selectedTask.stage) }}</span><span>耗时 {{ activitySeconds(activityElapsed(selectedTask,clock)) }}</span></div></div><div><NuxtLink v-if="selectedTask.drama_id || selectedTask.project_id" class="btn btn-sm" :to="`/drama/${selectedTask.drama_id || selectedTask.project_id}`" title="打开任务所属项目"><ArrowUpRight :size="13" />项目</NuxtLink><button v-if="canRequestCancel" class="btn btn-sm" @click="requestCancel" :disabled="cancelRequestPending||selectedTask.stage==='cancelling'">{{ cancelRequestPending?'正在请求…':selectedTask.stage==='cancelling'?'已请求取消':'请求取消' }}</button><button class="btn btn-sm" @click="downloadDetail" :disabled="!detail||exporting"><Download :size="13" />导出记录</button></div></header><div class="activity-model-meta"><span>{{ selectedTask.channel || '渠道未提供' }}</span><i></i><span>{{ selectedTask.model || '模型未提供' }}</span><template v-if="detail?.rounds?.length"><i></i><span>{{ detail.rounds.length }} 轮调用</span></template><template v-if="selectedTask.queue_seconds != null"><i></i><span>排队 {{ activitySeconds(selectedTask.queue_seconds) }}</span></template></div><div v-if="detailError" class="activity-error" role="alert">{{ detailError }}</div><div v-if="selectedTask.error || selectedTask.error_msg" class="activity-failure"><CircleAlert :size="16" /><div><strong>本次任务未完成</strong><p>{{ selectedTask.error || selectedTask.error_msg }}</p></div></div><div v-if="actualProgress!==null" class="activity-progress"><span>上游进度 <b>{{ Math.round(actualProgress) }}%</b></span><div><i :style="{width:actualProgress+'%'}"></i></div></div><div v-if="detail?.rounds?.length>1" class="activity-round-picker"><span>调用轮次</span><label class="follow-round"><input v-model="followLatest" type="checkbox" />跟随最新轮次</label><button v-for="(round,index) in detail.rounds" :key="round.id || index" :class="{on:roundIndex===index}" @click="selectRound(index)">第 {{ round.number || index+1 }} 轮<i v-if="round.status==='completed'"></i></button></div><nav class="activity-tabs"><button v-for="tab in tabs" :key="tab.key" :class="{on:activeTab===tab.key}" @click="activeTab=tab.key"><component :is="tab.icon" :size="13" />{{ tab.label }}</button></nav>
        <div class="activity-detail-content"><div v-if="detailLoading && !detail" class="activity-empty"><Loader2 :size="23" class="animate-spin" /><strong>正在读取详情…</strong></div><template v-else>
          <section v-if="activeTab==='output'" class="activity-output"><div class="activity-section-toolbar"><span>模型返回的公开内容</span><div><label><input v-model="autoScroll" type="checkbox" />自动滚动</label><button @click="copy(outputText)" :disabled="!outputText"><Copy :size="12" />复制</button></div></div><pre v-if="outputText" ref="outputElement" class="activity-output-box">{{ outputText }}</pre><div v-else class="activity-output-placeholder"><span :class="{working:activityTaskActive(selectedTask)}"><Activity v-if="activityTaskActive(selectedTask)" :size="23" /><MessageSquare v-else :size="25" /></span><h3>{{ activityTaskActive(selectedTask)?'任务正在处理':'暂无公开文字输出' }}</h3><p>{{ activityTaskActive(selectedTask)?'收到公开回复后会在这里显示，运行阶段可在「执行过程」中查看。':'图片和视频结果可在「用量与结果」查看。' }}</p></div></section>
          <section v-else-if="activeTab==='request'" class="activity-request"><div class="activity-section-toolbar"><span>{{ isAdmin?'本次调用的受控请求快照':'你有权查看的任务输入与参数' }}</span><button @click="copy(requestText)" :disabled="!requestText"><Copy :size="12" />复制</button></div><div class="activity-info-note"><ShieldCheck :size="13" /><span>{{ isAdmin?'密钥、Cookie 和媒体 Base64 已隐藏。系统提示词与 Skill 快照仅管理员可查。':'共享系统提示词和 Skill 原文由管理员管理；这里显示当前账号可查看的业务输入。' }}</span></div><pre class="activity-code-box">{{ requestText || '本任务未保存可查看的请求快照。' }}</pre></section>
          <section v-else-if="activeTab==='process'" class="activity-process"><div v-if="toolCalls.length" class="activity-tools"><h3>工具调用</h3><details v-for="(tool,index) in toolCalls" :key="tool.id || index"><summary><Wrench :size="13" /><strong>{{ tool.name || tool.function?.name || '业务工具' }}</strong><span>查看参数与结果</span></summary><pre>{{ formatActivityValue(tool) }}</pre></details></div><div class="activity-section-toolbar"><span>执行过程</span><small>{{ events.length }} 条公开记录</small></div><button v-if="detail?.events_page?.has_more && events.length < detail.events_page.total" class="btn btn-sm" style="margin-bottom:18px" :disabled="loadingEarlier" @click="loadEarlier">{{ loadingEarlier?'正在读取…':'加载更早记录' }} · {{ events.length }} / {{ detail.events_page.total }}</button><ol v-if="events.length" class="activity-timeline"><li v-for="event in events" :key="event.id"><span class="timeline-point" :class="{failure:/error|fail/.test(event.kind),active:/start|submit|running/.test(event.kind)}"></span><div class="timeline-title"><strong>{{ event.message || activityStageLabel(event.kind) }}</strong><time>{{ formatClock(event.created_at) }}</time></div><p v-if="event.kind && event.message">{{ activityStageLabel(event.kind) }}</p><details v-if="event.payload && Object.keys(event.payload).length"><summary>查看记录数据</summary><pre>{{ formatActivityValue(event.payload) }}</pre></details></li></ol><div v-else class="activity-empty"><Activity :size="25" /><strong>尚无过程记录</strong><p>旧任务可能只保留最终状态；新任务会记录更多阶段。</p></div></section>
          <section v-else class="activity-result"><div class="activity-usage-grid"><div><span>输入 Token</span><strong>{{ activityToken(usage,['input_tokens','prompt_tokens','inputTokens']) }}</strong></div><div><span>输出 Token</span><strong>{{ activityToken(usage,['output_tokens','completion_tokens','outputTokens']) }}</strong></div><div><span>总耗时</span><strong>{{ activitySeconds(activityElapsed(selectedTask,clock)) }}</strong></div><div><span>执行耗时</span><strong>{{ activitySeconds(selectedTask.run_seconds) }}</strong></div></div><p class="activity-usage-note">用量按服务实际返回记录；未返回时显示“未提供”。进度不会按等待时间推算。</p><div v-if="selectedTask.stage==='ready_in_local_service'" class="activity-manual-result"><CircleCheck :size="20" /><div><strong>已在服务端出片</strong><p>此通道采用服务端手动下载，结果尚未自动导入项目。</p></div></div><div v-else-if="selectedTask.stage==='handed_off'" class="activity-manual-result"><CircleCheck :size="20" /><div><strong>已交即梦</strong><p>即梦已接单，画布卡片已命名。出片时间由即梦决定；出片后会自动回传到分镜，也可以在剧集页点「回传视频」。</p></div></div><div v-if="resultAttachments.length" class="activity-attachments"><a v-for="(attachment,index) in resultAttachments" :key="index" :href="attachmentUrl(attachment)" download target="_blank" rel="noopener"><Download :size="12" />下载{{ selectedTask.kind==='image'?'图片':'视频' }} {{ index+1 }}</a></div><div v-if="resultText"><div class="activity-section-toolbar"><span>生成结果</span><button @click="copy(resultText)"><Copy :size="12" />复制</button></div><pre class="activity-code-box">{{ resultText }}</pre></div><div v-else-if="selectedTask.status==='completed'" class="activity-info-note"><CircleCheck :size="14" /><span>任务已完成，结果保存在所属项目或通道服务端。</span></div></section>
        </template></div><footer class="activity-detail-footer"><span><Database :size="11" />记录保存在服务端</span><span>{{ outputText.length.toLocaleString() }} 字符<template v-if="currentRound"> · 第 {{ currentRound.number || roundIndex+1 }} 轮</template></span></footer></template><div v-else class="activity-detail-empty"><span><Activity :size="31" /></span><h2>每一步，都有迹可循</h2><p>选择左侧任务，查看公开回复、实际参数、执行过程与结果。</p></div></main>
    </div>
  </section>
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Activity, RefreshCw, X, Search, ChevronRight, ChevronLeft, Type, FileText, Image as ImageIcon, Video, ListTodo, Loader2, ArrowUpRight, Download, CircleAlert, Copy, MessageSquare, ShieldCheck, Wrench, ChartNoAxesCombined, Database, CircleCheck } from 'lucide-vue-next'
import { toast } from 'vue-sonner'
import { activityAPI, taskAPI } from '~/composables/useApi'
import { platformSession } from '~/utils/platform-session'
import { activityTaskActive,activityKindLabel,activityStatusLabel,activityStageLabel,activityElapsed,activitySeconds,activityProgress,activityToken,activityPublicEvents,formatActivityValue,safeActivityValue,activityPublicText,mergeActivityEvents,activityRoundTools } from '~/utils/activity-tasks.js'
const props=defineProps({dramaId:{type:[Number,String],default:null},embedded:Boolean,closable:Boolean,initialTaskId:{type:String,default:''},initialRoundId:{type:String,default:''},initialTab:{type:String,default:'output'}})
const emit=defineEmits(['close','counts'])
const items=ref([]),total=ref(0),counts=ref({}),kind=ref(''),status=ref(''),keyword=ref(''),offset=ref(0),limit=40,selectedId=ref(''),detail=ref(null),loading=ref(false),detailLoading=ref(false),listError=ref(''),detailError=ref(''),activeTab=ref(props.initialTab||'output'),roundIndex=ref(0),clock=ref(Date.now()),connection=ref('connecting'),autoScroll=ref(true),outputElement=ref(null)
const earlierEvents=ref([]),loadingEarlier=ref(false),cancelRequestPending=ref(false)
const liveEvents=ref([]),followLatest=ref(true),pinnedRoundId=ref(null),exporting=ref(false)
const tabs=[{key:'output',label:'公开输出',icon:MessageSquare},{key:'request',label:'提交内容',icon:FileText},{key:'process',label:'执行过程',icon:Wrench},{key:'result',label:'用量与结果',icon:ChartNoAxesCombined}]
const isAdmin=computed(()=>platformSession.user?.role==='admin'),visibleItems=computed(()=>items.value.filter(task=>`${task.title||''} ${task.model||''} ${task.channel||''}`.toLowerCase().includes(keyword.value.toLowerCase())))
const allCount=computed(()=>Number(counts.value.active||0)+Number(counts.value.queued||0)+Number(counts.value.completed||0)+Number(counts.value.failed||0))
const selectedTask=computed(()=>detail.value?.task?.id===selectedId.value?detail.value.task:items.value.find(task=>task.id===selectedId.value))
const canRequestCancel=computed(()=>selectedTask.value?.result?.cancel_available===true&&selectedTask.value?.source_ref?.type==='media')
const currentRound=computed(()=>detail.value?.rounds?.[roundIndex.value]||null)
const outputText=computed(()=>{const round=currentRound.value;const saved=activityPublicText(round?.public_text??round?.public_output??round?.output??detail.value?.output);const deltas=events.value.filter(event=>event.kind==='public_delta'&&(!round?.id||event.round_id===round.id)).map(event=>event.payload?.text||'').join('');return saved||deltas})
const requestText=computed(()=>formatActivityValue(currentRound.value?.input??detail.value?.request))
const resultText=computed(()=>formatActivityValue(detail.value?.result))
const resultAttachments=computed(()=>{const result=detail.value?.result;const list=result?.output_images||result?.output_videos;return(Array.isArray(list)?list:result?.local_path||result?.result_url?[result]:[]).filter(item=>item.local_path||item.result_url)})
const attachmentUrl=item=>/^(?:https?:|\/)/u.test(item.local_path||item.result_url)?item.local_path||item.result_url:'/'+(item.local_path||item.result_url)
const usage=computed(()=>{const round=currentRound.value?.usage;return round&&Object.keys(round).length?round:detail.value?.usage||{}})
const events=computed(()=>mergeActivityEvents(earlierEvents.value,detail.value?.events||[],liveEvents.value))
const toolCalls=computed(()=>activityRoundTools(currentRound.value,events.value))
const actualProgress=computed(()=>activityProgress(selectedTask.value?.progress)),kindIcon=kind=>({text:Type,image:ImageIcon,video:Video,merge:Video}[kind]||Activity)
let alive=true,listSequence=0,detailSequence=0,eventSource=null,eventCursor='',debounce=null,pollTimer=null,reconnectTimer=null,clockTimer=null,linkedRoundApplied=false
const identity=platformSession.user?.id
const valid=()=>alive&&platformSession.user?.id===identity
function stateClass(task){if(task?.status==='completed')return 'is-completed';if(['failed','error','interrupted','cancelled'].includes(task?.status))return 'is-failed';if(['queued','pending'].includes(task?.status))return 'is-queued';return 'is-running'}
function formatDate(value){if(!value)return '时间未提供';const date=new Date(value);return Number.isNaN(date.getTime())?'时间未提供':date.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function formatClock(value){if(!value)return '';const date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleTimeString('zh-CN',{hour12:false})}
async function loadList(){const sequence=++listSequence;loading.value=true;try{const value=await activityAPI.list({drama_id:props.dramaId,kind:kind.value,status:status.value,offset:offset.value,limit});if(!valid()||sequence!==listSequence)return;items.value=value.items||[];total.value=value.total||0;counts.value=value.counts||{};emit('counts',counts.value);listError.value='';if(!selectedId.value&&items.value[0])await select(items.value[0].id)}catch(error){if(valid()&&sequence===listSequence)listError.value=error.message}finally{if(valid()&&sequence===listSequence)loading.value=false}}
async function loadDetail(){if(!selectedId.value)return;const id=selectedId.value,sequence=++detailSequence;detailLoading.value=true;try{const value=await activityAPI.detail(id);if(!valid()||sequence!==detailSequence||selectedId.value!==id)return;detail.value=value;detailError.value='';if(!linkedRoundApplied&&props.initialRoundId&&id===props.initialTaskId){const found=(value.rounds||[]).findIndex(round=>String(round.id)===String(props.initialRoundId));if(found>=0){roundIndex.value=found;pinnedRoundId.value=value.rounds[found].id;followLatest.value=false;autoScroll.value=false;linkedRoundApplied=true}else{detailError.value='指定轮次尚未记录，可刷新原任务继续查看。'}}else if(followLatest.value)roundIndex.value=Math.max(0,(value.rounds?.length||1)-1);else{const pinned=(value.rounds||[]).findIndex(round=>round.id===pinnedRoundId.value);if(pinned>=0)roundIndex.value=pinned;else if(roundIndex.value>=(value.rounds?.length||1))roundIndex.value=0}if(autoScroll.value){await nextTick();if(outputElement.value)outputElement.value.scrollTop=outputElement.value.scrollHeight}}catch(error){if(valid()&&sequence===detailSequence)detailError.value=error.message}finally{if(valid()&&sequence===detailSequence)detailLoading.value=false}}
async function select(id){if(selectedId.value!==id){selectedId.value=id;detail.value=null;roundIndex.value=0;detailError.value='';liveEvents.value=[];earlierEvents.value=[];followLatest.value=true;pinnedRoundId.value=null}await loadDetail()}
async function refreshAll(){await Promise.all([loadList(),loadDetail()])}
function scheduleRefresh(event){clearTimeout(debounce);debounce=setTimeout(()=>{if(!valid())return;loadList();if(!event?.task_id||event.task_id===selectedId.value||activityTaskActive(selectedTask.value))loadDetail()},650)}
function startPolling(){if(pollTimer)return;pollTimer=setInterval(()=>{if(valid()&&document.visibilityState!=='hidden')refreshAll()},5000)}
function connect(){if(!valid()||typeof EventSource==='undefined'){connection.value='polling';startPolling();return}eventSource?.close();clearTimeout(reconnectTimer);connection.value='connecting';const source=new EventSource(activityAPI.eventsUrl({drama_id:props.dramaId,after:eventCursor}),{withCredentials:true});eventSource=source;source.onopen=()=>{if(!valid())return;connection.value='live';clearInterval(pollTimer);pollTimer=null};source.onmessage=message=>{if(!valid())return;try{const event=JSON.parse(message.data);eventCursor=message.lastEventId||event.id||eventCursor;if(event.task_id===selectedId.value){liveEvents.value=mergeActivityEvents(liveEvents.value,[event]).slice(-2000);if(autoScroll.value)nextTick(()=>{if(outputElement.value)outputElement.value.scrollTop=outputElement.value.scrollHeight})}scheduleRefresh(event)}catch{}};source.onerror=()=>{if(!valid())return;source.close();if(eventSource===source)eventSource=null;connection.value='polling';startPolling();reconnectTimer=setTimeout(connect,15000)}}
async function requestCancel(){if(!canRequestCancel.value||cancelRequestPending.value||selectedTask.value.stage==='cancelling')return;if(!window.confirm('确认请求取消该上游任务？结果需要等待上游确认，系统将继续查询原任务。'))return;const sourceId=selectedTask.value.source_ref.id;cancelRequestPending.value=true;try{await taskAPI.cancel(sourceId);toast.info('已发送取消请求，等待上游确认。');await refreshAll()}catch(error){toast.error(error.message||'请求取消失败')}finally{cancelRequestPending.value=false}}
async function copy(value){try{await navigator.clipboard.writeText(value);toast.success('已复制')}catch{toast.error('复制失败，请手动选择内容复制。')}}
async function downloadDetail(){if(!detail.value||exporting.value)return;exporting.value=true;try{const bytes=await activityAPI.export(selectedId.value),url=URL.createObjectURL(bytes),a=document.createElement('a');a.href=url;a.download=`创作记录-${String(selectedId.value).replace(/[^A-Za-z0-9_-]/g,'')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error){toast.error(error.message||'导出失败')}finally{exporting.value=false}}
async function loadEarlier(){if(!selectedId.value||loadingEarlier.value)return;loadingEarlier.value=true;const id=selectedId.value;try{const before=events.value[0]?.id;const value=await activityAPI.events(id,{before,limit:500});if(valid()&&selectedId.value===id)earlierEvents.value=mergeActivityEvents(value.items||[],earlierEvents.value)}catch(error){toast.error(error.message)}finally{loadingEarlier.value=false}}
function selectRound(index){roundIndex.value=index;followLatest.value=false;autoScroll.value=false;pinnedRoundId.value=detail.value?.rounds?.[index]?.id||null;linkedRoundApplied=true}
function clearSelection(){selectedId.value='';detail.value=null;detailError.value='';liveEvents.value=[];++detailSequence}
watch(followLatest,value=>{if(value){roundIndex.value=Math.max(0,(detail.value?.rounds?.length||1)-1);autoScroll.value=true}else pinnedRoundId.value=currentRound.value?.id||null})
watch([kind,status],()=>{clearSelection();if(offset.value!==0)offset.value=0;else loadList()});watch(offset,()=>{clearSelection();loadList()})
watch(()=>props.dramaId,()=>{items.value=[];selectedId.value=props.initialTaskId||'';detail.value=null;offset.value=0;eventCursor='';linkedRoundApplied=false;loadList();if(selectedId.value)loadDetail();connect()})
watch(()=>props.initialTaskId,id=>{if(!id)return;linkedRoundApplied=false;select(id)})
watch(()=>props.initialRoundId,()=>{linkedRoundApplied=false;if(selectedId.value)loadDetail()})
watch(()=>props.initialTab,value=>{if(tabs.some(tab=>tab.key===value))activeTab.value=value})
onMounted(()=>{if(props.initialTaskId)selectedId.value=props.initialTaskId;loadList();if(selectedId.value)loadDetail();connect();clockTimer=setInterval(()=>{clock.value=Date.now()},1000)})
onBeforeUnmount(()=>{alive=false;++listSequence;++detailSequence;eventSource?.close();clearTimeout(debounce);clearTimeout(reconnectTimer);clearInterval(pollTimer);clearInterval(clockTimer)})
